/* Customer portal polish: compact command bar + quick actions. */

/* The customer is already signed in, so do not repeat login/apply in the global header. */
.account-page .nav-actions > a[href="login.html"],
.account-page .nav-actions .js-apply { display:none; }

.account-page .account-shell { padding-top:28px; }

.account-command-bar {
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:center;
  gap:22px;
  margin-bottom:24px;
  padding:16px 18px;
  border-radius:22px;
  color:#fff;
  background:linear-gradient(110deg,var(--brand-primary-strong,#0558ad),var(--brand-primary,#0876d8),var(--brand-secondary,#18b5d6));
  box-shadow:0 18px 42px rgba(5,57,99,.16);
}

.account-command-greeting { min-width:150px; }
.account-command-greeting > span {
  display:block;
  margin-bottom:2px;
  color:rgba(255,255,255,.72);
  font-size:.66rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.account-command-greeting h1 {
  margin:0;
  color:#fff;
  font-size:1.45rem;
  line-height:1.1;
  letter-spacing:-.025em;
  font-weight:650;
}
.account-command-greeting h1 strong { font-weight:850; }

.account-command-bar .portal-tabs {
  min-width:0;
  display:flex;
  gap:5px;
  margin:0;
  padding:5px;
  overflow:auto;
  border:1px solid rgba(255,255,255,.16);
  border-radius:14px;
  background:rgba(255,255,255,.09);
  scrollbar-width:none;
}
.account-command-bar .portal-tabs::-webkit-scrollbar { display:none; }
.account-command-bar .portal-tabs button {
  flex:0 0 auto;
  padding:9px 13px;
  border:0;
  border-radius:10px;
  color:rgba(255,255,255,.78);
  background:transparent;
  font-size:.82rem;
  font-weight:750;
}
.account-command-bar .portal-tabs button:hover { color:#fff;background:rgba(255,255,255,.10); }
.account-command-bar .portal-tabs button.active {
  color:var(--brand-primary-strong,#0558ad);
  background:#fff;
  box-shadow:0 5px 14px rgba(5,57,99,.10);
}

.account-command-actions {
  display:flex;
  align-items:center;
  gap:8px;
  white-space:nowrap;
}
.account-command-actions .account-apply-button {
  min-height:40px;
  padding:0 15px;
  border:1px solid rgba(255,255,255,.22);
  border-radius:11px;
  color:#fff;
  background:rgba(255,255,255,.16);
  box-shadow:none;
  font-size:.78rem;
}
.account-command-actions .account-apply-button:hover { background:rgba(255,255,255,.24); }
.account-logout-button {
  min-height:40px;
  padding:0 12px;
  border:0;
  color:rgba(255,255,255,.78);
  background:transparent;
  font:inherit;
  font-size:.76rem;
  font-weight:750;
  cursor:pointer;
}
.account-logout-button:hover { color:#fff; }

.portal-summary { margin-top:0; }

.portal-shortcuts { margin-top:18px; }
.portal-shortcuts .portal-panel-head { margin-bottom:16px; }
.portal-shortcuts .portal-panel-head h2 { font-size:1.35rem;letter-spacing:-.02em; }

.portal-action-grid { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px; }
.portal-action-card {
  position:relative;
  min-width:0;
  min-height:132px;
  display:grid;
  grid-template-columns:50px 1fr auto;
  gap:14px;
  align-items:center;
  padding:20px;
  overflow:hidden;
  border:1px solid transparent;
  border-radius:20px;
  text-align:left;
  color:var(--brand-navy,#073f5a);
  font:inherit;
  cursor:pointer;
  transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease;
}
.portal-action-card::after {
  content:"";
  position:absolute;
  width:110px;height:110px;top:-55px;right:-42px;
  border-radius:50%;background:rgba(255,255,255,.42);pointer-events:none;
}
.action-applications { background:linear-gradient(145deg,rgba(var(--brand-primary-rgb,8,118,216),.15),rgba(var(--brand-primary-rgb,8,118,216),.06));border-color:rgba(var(--brand-primary-rgb,8,118,216),.17); }
.action-loans { background:linear-gradient(145deg,rgba(var(--brand-accent-rgb,86,197,31),.18),rgba(var(--brand-accent-rgb,86,197,31),.06));border-color:rgba(var(--brand-accent-rgb,86,197,31),.20); }
.action-details { background:linear-gradient(145deg,rgba(24,181,214,.18),rgba(24,181,214,.06));border-color:rgba(24,181,214,.20); }
.portal-action-icon { width:50px;height:50px;display:grid;place-items:center;border-radius:16px;color:#fff;font-size:1rem;font-weight:800;box-shadow:0 10px 24px rgba(5,57,99,.12); }
.action-applications .portal-action-icon { background:var(--brand-primary,#0876d8); }
.action-loans .portal-action-icon { background:var(--brand-accent-strong,#38a814); }
.action-details .portal-action-icon { background:var(--brand-secondary,#18b5d6); }
.portal-action-copy { min-width:0;display:grid;gap:4px; }
.portal-action-copy strong { color:var(--brand-navy,#073f5a);font-size:1.08rem;line-height:1.2;font-weight:760; }
.portal-action-copy small { color:var(--brand-muted,#668098);font-size:.78rem;font-weight:620; }
.portal-action-arrow { position:relative;z-index:1;width:34px;height:34px;display:grid;place-items:center;border-radius:12px;color:var(--brand-navy,#073f5a);background:rgba(255,255,255,.72);font-size:1.05rem;font-weight:800; }
.portal-action-card:hover,.portal-action-card:focus-visible { transform:translateY(-3px);box-shadow:0 16px 34px rgba(5,57,99,.10);outline:none; }
.action-applications:hover,.action-applications:focus-visible { border-color:rgba(var(--brand-primary-rgb,8,118,216),.34); }
.action-loans:hover,.action-loans:focus-visible { border-color:rgba(var(--brand-accent-rgb,86,197,31),.38); }
.action-details:hover,.action-details:focus-visible { border-color:rgba(24,181,214,.38); }

@media(max-width:1050px){
  .account-command-bar { grid-template-columns:auto minmax(0,1fr); }
  .account-command-actions { grid-column:1/-1;justify-content:flex-end;margin-top:-4px; }
}

@media(max-width:900px){
  .account-page .account-shell { padding-top:18px; }
  .account-command-bar { grid-template-columns:1fr;gap:12px;padding:15px;border-radius:18px; }
  .account-command-greeting { min-width:0; }
  .account-command-greeting h1 { font-size:1.3rem; }
  .account-command-bar .portal-tabs { width:100%; }
  .account-command-actions { grid-column:auto;justify-content:space-between;margin-top:0; }
  .portal-action-grid { grid-template-columns:1fr; }
  .portal-action-card { min-height:104px; }
}

@media(max-width:520px){
  .account-page .account-shell { padding-top:10px; }
  .account-command-bar { margin-bottom:14px;padding:13px 12px; }
  .account-command-greeting > span { display:none; }
  .account-command-greeting h1 { font-size:1.2rem; }
  .account-command-bar .portal-tabs { margin-left:-2px;margin-right:-2px;width:calc(100% + 4px); }
  .account-command-bar .portal-tabs button { padding:8px 10px;font-size:.75rem; }
  .account-command-actions .account-apply-button { flex:1; }
  .portal-action-card { grid-template-columns:44px 1fr auto;min-height:92px;padding:16px; }
  .portal-action-icon { width:44px;height:44px;border-radius:14px; }
  .portal-action-copy strong { font-size:1rem; }
}

.application-focus-card{
  margin-top:18px;
  padding:18px 20px;
  border:1px solid rgba(var(--brand-primary-rgb,8,118,216),.16);
  border-radius:20px;
  background:linear-gradient(135deg,#fff,#f3f8ff 64%,#f1fbf7);
  box-shadow:0 12px 32px rgba(5,57,99,.07);
}
.application-focus-top,.application-focus-bottom{display:flex;align-items:center;justify-content:space-between;gap:18px}
.application-focus-top>div{display:grid;gap:2px}
.application-focus-top span{color:var(--brand-muted,#668098);font-size:.68rem;font-weight:800;text-transform:uppercase;letter-spacing:.07em}
.application-focus-top strong{color:var(--brand-navy,#073f5a);font-size:1.28rem;line-height:1.15}
.application-focus-top small{color:var(--brand-muted,#668098);font-size:.7rem}
.application-focus-top>b{color:var(--brand-primary-strong,#0558ad);font-size:1.28rem;white-space:nowrap}
.application-stage-track{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin:17px 0 15px}
.application-stage-track>div{position:relative;display:grid;grid-template-rows:28px auto;justify-items:start;align-items:center;row-gap:5px;color:#8090a0;font-size:.76rem;font-weight:750;min-width:0}
.application-stage-track>div:not(:last-child)::after{content:"";position:absolute;left:28px;top:13px;width:calc(100% - 14px);height:2px;background:#dbe5ee;z-index:0}
.application-stage-track i{position:relative;z-index:2;width:28px;height:28px;display:grid;place-items:center;border:2px solid #d9e4ed;border-radius:50%;background:#fff;color:#8190a0;font-size:.68rem;font-style:normal;font-weight:900}
.application-stage-track>div span{position:relative;z-index:2;line-height:1.2;white-space:nowrap}
.application-stage-track .done,.application-stage-track .active{color:var(--brand-navy,#073f5a)}
.application-stage-track .done i{border-color:#a8dfc5;background:#eaf8f1;color:#198b59}
.application-stage-track .active i{border-color:var(--brand-primary,#0876d8);background:var(--brand-primary,#0876d8);color:#fff;box-shadow:0 0 0 5px rgba(var(--brand-primary-rgb,8,118,216),.09)}
.application-stage-track .done:not(:last-child)::after{background:linear-gradient(90deg,#6fc49a,var(--brand-primary,#0876d8))}
.application-focus-bottom{padding-top:13px;border-top:1px solid rgba(var(--brand-primary-rgb,8,118,216),.10)}
.application-focus-bottom strong{color:var(--brand-navy,#073f5a);font-size:.82rem}
.application-focus-bottom button{border:0;background:transparent;color:var(--brand-primary-strong,#0558ad);font:inherit;font-size:.78rem;font-weight:850;cursor:pointer}
.application-focus-card[data-status="approved"]{border-color:rgba(var(--brand-accent-rgb,86,197,31),.30);background:linear-gradient(135deg,#fff,#f0faeb)}
.application-focus-card[data-status="needs_information"],.application-focus-card[data-status="documents_requested"]{border-color:#efc57f;background:linear-gradient(135deg,#fff,#fff7e9)}
.latest-application-summary strong{font-size:1.35rem!important;line-height:1.15}
.latest-application-summary strong small{margin-top:7px!important}
@media(max-width:640px){
  .application-focus-card{padding:16px}
  .application-focus-top strong,.application-focus-top>b{font-size:1.08rem}
  .application-stage-track>div{grid-template-rows:26px auto;row-gap:5px;font-size:.68rem}
  .application-stage-track>div:not(:last-child)::after{left:26px;top:12px;width:calc(100% - 13px)}
  .application-stage-track i{width:26px;height:26px}
  .application-focus-bottom{align-items:flex-start}
}

/* KredRun collection-date loan calculator.
 * Colours stay connected to assets/css/theme.css.
 */

.collection-calculator {
  padding: 0;
  overflow: hidden;
  border-radius: 30px;
  background: rgba(255,255,255,.985);
}

.collection-calculator:before { display: none; }

.collection-calculator .calculator-topline {
  padding: 25px 28px 21px;
}

.calculator-product-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(var(--brand-accent-rgb), .22);
  border-radius: 999px;
  color: var(--brand-accent-strong);
  background: var(--surface-success);
  font-size: .66rem;
  font-weight: 900;
  white-space: nowrap;
}

.calculator-product-badge:before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brand-accent);
  box-shadow: 0 0 0 4px rgba(var(--brand-accent-rgb), .10);
}

.loan-control-section {
  padding: 22px 28px 0;
}

.loan-control-section + .loan-control-section {
  margin-top: 2px;
}

.loan-control-head {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-end;
  margin-bottom: 13px;
}

.loan-control-head > div:first-child { min-width: 0; }

.loan-control-title {
  display: block;
  color: var(--brand-navy);
  font-size: .78rem;
  font-weight: 900;
}

.loan-control-help {
  display: block;
  margin-top: 2px;
  color: var(--brand-muted);
  font-size: .65rem;
  line-height: 1.35;
}

.amount-editor {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-width: 174px;
  height: 52px;
  padding: 0 13px;
  border: 1px solid rgba(var(--brand-primary-rgb), .16);
  border-radius: 15px;
  background: var(--surface-soft);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.8);
}

.amount-editor:focus-within {
  border-color: rgba(var(--brand-primary-rgb), .52);
  box-shadow: 0 0 0 4px rgba(var(--brand-primary-rgb), .08);
  background: #fff;
}

.amount-editor span {
  margin-right: 3px;
  color: var(--brand-primary-strong);
  font-size: 1.55rem;
  font-weight: 900;
}

.amount-editor input {
  width: 120px;
  min-width: 0;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--brand-navy);
  background: transparent;
  font: inherit;
  font-size: 1.8rem;
  font-weight: 900;
  letter-spacing: -.045em;
  appearance: textfield;
  -moz-appearance: textfield;
}

.amount-editor input::-webkit-inner-spin-button,
.amount-editor input::-webkit-outer-spin-button {
  margin: 0;
  -webkit-appearance: none;
}

.wheel-range {
  --range-progress: 25%;
  width: 100%;
  height: 9px;
  margin: 8px 0 2px;
  border: 0;
  border-radius: 999px;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
  background: linear-gradient(90deg, var(--brand-accent) 0 var(--range-progress), #dce7ef var(--range-progress) 100%);
}

.wheel-range::-webkit-slider-thumb {
  width: 26px;
  height: 26px;
  border: 5px solid #fff;
  border-radius: 50%;
  appearance: none;
  -webkit-appearance: none;
  background: var(--brand-accent);
  box-shadow: 0 0 0 1px rgba(var(--brand-accent-rgb), .34), 0 5px 15px rgba(var(--brand-navy-rgb), .18);
  cursor: grab;
}

.wheel-range::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: 5px solid #fff;
  border-radius: 50%;
  background: var(--brand-accent);
  box-shadow: 0 0 0 1px rgba(var(--brand-accent-rgb), .34), 0 5px 15px rgba(var(--brand-navy-rgb), .18);
  cursor: grab;
}

.wheel-range:focus-visible {
  box-shadow: 0 0 0 4px rgba(var(--brand-primary-rgb), .10);
}

.wheel-range:active::-webkit-slider-thumb { cursor: grabbing; }

.wheel-endpoints,
.date-wheel-markers {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: var(--brand-muted);
  font-size: .63rem;
}

.wheel-endpoints { margin-top: 7px; }

.collection-date-display {
  flex: 0 0 auto;
  min-width: 184px;
  padding: 10px 13px;
  border: 1px solid rgba(var(--brand-primary-rgb), .12);
  border-radius: 15px;
  text-align: right;
  background: linear-gradient(145deg, #fff, var(--surface-tint));
}

.collection-date-display strong,
.collection-date-display span {
  display: block;
}

.collection-date-display strong {
  color: var(--brand-primary-strong);
  font-size: .95rem;
  line-height: 1.1;
}

.collection-date-display span {
  margin-top: 3px;
  color: var(--brand-muted);
  font-size: .64rem;
  font-weight: 750;
}

.date-wheel-track {
  position: relative;
  margin-top: 4px;
}

.date-wheel-markers {
  margin-top: 9px;
}

.date-wheel-markers span:nth-child(2),
.date-wheel-markers span:nth-child(3) { text-align: center; }
.date-wheel-markers span:last-child { text-align: right; }

.price-summary {
  margin: 23px 28px 0;
  overflow: hidden;
  border: 1px solid rgba(var(--brand-primary-rgb), .12);
  border-radius: 20px;
  background: linear-gradient(145deg, #f8fcff, #eef7fc);
}

.price-summary-top {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 18px;
  align-items: end;
  padding: 17px 18px 15px;
  border-bottom: 1px solid rgba(var(--brand-primary-rgb), .10);
}

.price-summary-top span,
.price-summary-top small,
.price-summary-top strong { display: block; }

.price-summary-top span {
  color: var(--brand-muted);
  font-size: .66rem;
  font-weight: 800;
}

.price-summary-top strong {
  margin-top: 3px;
  color: var(--brand-navy);
  font-size: 1.65rem;
  line-height: 1;
  letter-spacing: -.04em;
}

.price-summary-top small {
  max-width: 154px;
  color: var(--brand-muted);
  text-align: right;
  font-size: .59rem;
  line-height: 1.35;
}

.price-summary-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.price-summary-item {
  min-width: 0;
  padding: 14px 18px;
}

.price-summary-item + .price-summary-item {
  border-left: 1px solid rgba(var(--brand-primary-rgb), .10);
}

.price-summary-item > span {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--brand-muted);
  font-size: .64rem;
  font-weight: 780;
}

.price-summary-item > strong {
  display: block;
  margin-top: 4px;
  color: var(--brand-primary-strong);
  font-size: .9rem;
}

.fee-info-button {
  width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(var(--brand-primary-rgb), .28);
  border-radius: 50%;
  color: var(--brand-primary-strong);
  background: #fff;
  font: inherit;
  font-size: .67rem;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
}

.fee-info-button:hover,
.fee-info-button:focus-visible {
  color: #fff;
  background: var(--brand-primary);
  border-color: var(--brand-primary);
  outline: 0;
}

.collection-calculator .calculator-assurance {
  margin-top: 14px;
}

.collection-calculator .calculator-cta {
  margin-top: 15px;
}

.collection-calculator .loan-note {
  margin-bottom: 21px;
}

.fee-dialog {
  width: min(calc(100% - 32px), 430px);
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 22px;
  color: var(--brand-ink);
  background: #fff;
  box-shadow: 0 28px 90px rgba(var(--brand-navy-rgb), .28);
}

.fee-dialog::backdrop {
  background: rgba(5, 31, 54, .54);
  backdrop-filter: blur(3px);
}

.fee-dialog-head {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  padding: 16px 18px;
  color: #fff;
  background: var(--gradient-brand);
}

.fee-dialog-head strong { font-size: .95rem; }

.fee-dialog-close {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255,255,255,.24);
  border-radius: 10px;
  color: #fff;
  background: rgba(255,255,255,.10);
  font: inherit;
  font-size: 1.15rem;
  cursor: pointer;
}

.fee-dialog-total {
  padding: 14px 18px;
  color: var(--brand-primary-strong);
  background: var(--surface-tint);
  border-bottom: 1px solid var(--brand-line);
  font-size: .83rem;
  font-weight: 900;
}

.fee-breakdown-list {
  margin: 0;
  padding: 0 18px;
}

.fee-breakdown-row {
  display: flex;
  justify-content: space-between;
  gap: 22px;
  align-items: center;
  min-height: 49px;
  border-bottom: 1px solid var(--brand-line);
}

.fee-breakdown-row dt,
.fee-breakdown-row dd { margin: 0; }

.fee-breakdown-row dt {
  color: #526b80;
  font-size: .78rem;
}

.fee-breakdown-row dd {
  color: var(--brand-navy);
  font-size: .8rem;
  font-weight: 850;
  text-align: right;
}

.fee-breakdown-row.total-row dt,
.fee-breakdown-row.total-row dd {
  color: var(--brand-primary-strong);
  font-weight: 900;
}

.fee-dialog-note {
  margin: 0;
  padding: 15px 18px 18px;
  color: var(--brand-muted);
  font-size: .64rem;
  line-height: 1.5;
}

.fee-dialog-note strong { color: var(--brand-navy); }

@media (max-width: 620px) {
  .collection-calculator .calculator-topline,
  .loan-control-section { padding-left: 20px; padding-right: 20px; }

  .loan-control-head {
    align-items: stretch;
    flex-direction: column;
  }

  .amount-editor,
  .collection-date-display {
    width: 100%;
    min-width: 0;
  }

  .amount-editor input { width: 100%; }

  .collection-date-display { text-align: left; }

  .price-summary { margin-left: 20px; margin-right: 20px; }
  .price-summary-top { grid-template-columns: 1fr; }
  .price-summary-top small { max-width: none; text-align: left; }
  .collection-calculator .calculator-assurance { margin-left: 20px; margin-right: 20px; }
  .collection-calculator .calculator-cta { width: calc(100% - 40px); margin-left: 20px; margin-right: 20px; }
  .collection-calculator .loan-note { margin-left: 20px; margin-right: 20px; }
}

/*
 * KredRun shared design system
 * ------------------------------------------------------------
 * Shared visual language for website, client portal and lender admin.
 * Brand values come from assets/js/brand-config.js.
 */
@import url("mfa-security-polish.css");

:root{
  --brand-primary:#0876d8;
  --brand-primary-strong:#0558ad;
  --brand-secondary:#18b5d6;
  --brand-accent:#56c51f;
  --brand-accent-strong:#38a814;
  --brand-navy:#053963;
  --brand-ink:#0c2947;
  --brand-background:#f3f8fc;
  --brand-surface:#fff;
  --brand-muted:#668098;
  --brand-line:#d9e6f0;
  --brand-danger:#c6424f;
  --brand-warning:#d8891d;
  --brand-success:#22955f;
  --brand-primary-rgb:8,118,216;
  --brand-accent-rgb:86,197,31;
  --brand-navy-rgb:5,57,99;

  --ink:var(--brand-ink);
  --muted:var(--brand-muted);
  --blue:var(--brand-primary);
  --blue-dark:var(--brand-primary-strong);
  --aqua:var(--brand-secondary);
  --navy:var(--brand-navy);
  --navy-2:#031d39;
  --cloud:var(--brand-background);
  --line:var(--brand-line);
  --surface:var(--brand-surface);
  --canvas:var(--brand-background);
  --success:var(--brand-success);
  --orange:var(--brand-warning);
  --green:var(--brand-success);
  --red:var(--brand-danger);

  --ds-radius-xs:8px;
  --ds-radius-sm:10px;
  --ds-radius-md:12px;
  --ds-radius-lg:18px;
  --ds-radius-xl:22px;
  --radius:var(--ds-radius-md);
  --shadow:0 8px 28px rgba(var(--brand-navy-rgb),.08);
  --ds-shadow-sm:0 4px 18px rgba(var(--brand-navy-rgb),.07);
  --ds-shadow-md:0 12px 34px rgba(var(--brand-navy-rgb),.10);
  --ds-focus:0 0 0 3px rgba(var(--brand-primary-rgb),.16);
  --ds-gradient-brand:linear-gradient(125deg,var(--brand-primary-strong),var(--brand-primary) 56%,var(--brand-secondary));
  --ds-gradient-accent:linear-gradient(135deg,var(--brand-accent),var(--brand-accent-strong));
}

html{font-family:Manrope,Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
body,button,input,select,textarea{font-family:Manrope,Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}

/* Shared focus and control behaviour */
a,button,input,select,textarea{outline:none}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{box-shadow:var(--ds-focus);outline:2px solid transparent}
input,select,textarea{border-color:var(--brand-line)}
input:focus,select:focus,textarea:focus{border-color:var(--brand-primary)}

/* Shared buttons. Marketing pages may use larger spacing, but the shape and colour language stay the same. */
.btn,.primary-button,.secondary-button,.orange-button,.row-action,.text-button,.account-logout-button,.account-apply-button{
  border-radius:var(--ds-radius-sm);
  font-weight:700;
}
.btn,.primary-button,.secondary-button,.orange-button{min-height:44px}
.btn-primary,.primary-button{background:var(--brand-primary);color:#fff;border-color:var(--brand-primary);box-shadow:0 5px 14px rgba(var(--brand-primary-rgb),.18)}
.btn-primary:hover,.primary-button:hover{background:var(--brand-primary-strong);border-color:var(--brand-primary-strong)}
.btn-outline,.secondary-button{background:#fff;color:var(--brand-navy);border:1px solid var(--brand-line)}
.btn-outline:hover,.secondary-button:hover{color:var(--brand-primary-strong);border-color:var(--brand-primary)}
.orange-button{background:var(--brand-warning);color:#fff}

/* Shared surfaces */
.card,.panel,.portal-panel,.summary-card,.loan-card,.application-focus-card,.metric-card,.list-toolbar,.document-card,.auth-card,.received-card{
  border-color:var(--brand-line);
  box-shadow:var(--ds-shadow-sm);
}
.panel,.portal-panel,.summary-card,.metric-card,.list-toolbar,.document-card,.auth-card,.received-card{border-radius:var(--ds-radius-md)}

/* Shared status colours */
.status-approved,.status-active,.status-paid,.status-verified,.status-complete,.status-success{background:#e9f6e5!important;color:#2f7e22!important}
.status-under_review,.status-pending,.status-scheduled,.status-ready,.status-warning{background:#fff1de!important;color:#a95d0b!important}
.status-declined,.status-overdue,.status-rejected,.status-failed,.status-written_off,.status-danger{background:#ffe7e9!important;color:#b62f3a!important}
.status-received,.status-needs_review,.status-info{background:#e7f3fd!important;color:var(--brand-primary-strong)!important}

/* Shared brand marks */
.brand-mark,.admin-brand>span,.loading-mark,.account-boot-mark{
  background:var(--ds-gradient-brand)!important;
  color:#fff;
}
.brand-mark img,.admin-brand>span img,.loading-mark img,.account-boot-mark img{width:100%;height:100%;object-fit:contain;border-radius:inherit}

/* Admin inherits the same tenant colours while keeping the compact layout the user likes. */
.admin-page{background:var(--brand-background);color:var(--brand-ink)}
.admin-sidebar{background:linear-gradient(180deg,#031d39,var(--brand-navy))}
.admin-nav button.active{background:var(--brand-primary)}
.admin-brand{letter-spacing:-.025em}
.admin-brand>span{border-radius:var(--ds-radius-sm)}
.admin-topbar,.panel,.metric-card,.list-toolbar{border-color:var(--brand-line)}

/* Client portal keeps its richer borrower-friendly command bar, but now uses the shared tokens. */
.account-command-bar{background:var(--ds-gradient-brand)!important;border-radius:var(--ds-radius-lg)!important;box-shadow:var(--ds-shadow-md)!important}
.account-command-bar .portal-tabs{border-radius:var(--ds-radius-md)!important}
.account-command-bar .portal-tabs button{border-radius:var(--ds-radius-sm)!important}
.portal-action-card{border-radius:var(--ds-radius-lg)!important}
.portal-action-icon{border-radius:var(--ds-radius-md)!important}
.account-command-actions .account-apply-button{border-radius:var(--ds-radius-sm)!important}

/* Public site: same design DNA, with more breathing room for marketing. */
.site-header{border-color:var(--brand-line)}
.brand-mark{border-radius:var(--ds-radius-sm)}
.site-header .btn,.clean-actions .btn,.calculator-cta{border-radius:var(--ds-radius-sm)!important}
.loan-card{border-radius:var(--ds-radius-lg)}

@media(max-width:720px){
  .btn,.primary-button,.secondary-button,.orange-button{min-height:46px}
}

/* KredRun homepage refresh — intentionally scoped to .home-clean */
.home-clean{background:#fff;color:var(--ink)}
.home-clean .container{width:min(calc(100% - 36px),1120px)}
.home-clean .section{padding:92px 0}
.home-clean .section-soft{background:linear-gradient(180deg,#f4f8ff 0%,#f8fbff 52%,#ffffff 100%)}
.home-clean .home-eyebrow{display:block;margin:0 0 10px;color:#7a8492;font-size:.68rem;font-weight:900;letter-spacing:.12em;text-transform:uppercase}
.home-clean .home-title{margin:0;color:#101827;font-size:clamp(2rem,4vw,3.35rem);line-height:1.03;letter-spacing:-.05em}
.home-clean .home-lead{max-width:620px;margin:14px 0 0;color:#667085;font-size:1rem;line-height:1.65}
.home-clean .home-center{text-align:center}
.home-clean .home-center .home-lead{margin-left:auto;margin-right:auto}

/* Hero */
.home-clean .clean-hero{padding:34px 0 0;background:
  radial-gradient(circle at 12% 18%,rgba(32,199,201,.18),transparent 30%),
  radial-gradient(circle at 84% 8%,rgba(13,110,253,.28),transparent 32%),
  linear-gradient(135deg,#071d36 0%,#0b3f7f 48%,#0d6efd 100%)}
.home-clean .clean-hero-shell{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(390px,.72fr);gap:0;align-items:center;min-height:510px}
.home-clean .clean-hero-visual{position:relative;min-height:445px;overflow:hidden;border-radius:28px 0 0 28px;background:linear-gradient(145deg,#0a315f,#0d6efd)}
.home-clean .clean-hero-visual img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center}
.home-clean .clean-hero-overlay{position:absolute;inset:auto 24px 24px 24px;max-width:470px;padding:20px 22px;border:1px solid rgba(255,255,255,.24);border-radius:18px;color:#fff;background:linear-gradient(135deg,rgba(7,29,54,.82),rgba(13,110,253,.46));backdrop-filter:blur(12px)}
.home-clean .clean-hero-overlay h1{margin:0;font-size:clamp(1.9rem,3vw,3rem);line-height:1.02;letter-spacing:-.045em}
.home-clean .clean-hero-overlay p{margin:9px 0 0;color:rgba(255,255,255,.8);font-size:.88rem;line-height:1.55}
.home-clean .clean-hero .loan-card{z-index:2;margin-left:-32px;border:0;border-radius:26px;padding:26px;background:#fff;box-shadow:0 24px 70px rgba(0,24,70,.28)}
.home-clean .clean-hero .loan-card:before{display:none}
.home-clean .clean-hero-bottom{height:78px;margin-top:-38px;background:linear-gradient(180deg,rgba(255,255,255,.98),#fff);border-radius:34px 34px 0 0}

/* trust strip */
.home-clean .safety-wrap{margin-top:-40px;position:relative;z-index:3}
.home-clean .safety-strip{display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;padding:18px 20px;border-radius:20px;color:#fff;background:linear-gradient(110deg,#071d36 0%,#0b3f7f 55%,#0d6efd 100%);box-shadow:0 14px 35px rgba(13,110,253,.16)}
.home-clean .safety-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:14px;background:rgba(255,255,255,.12);font-size:1.25rem}
.home-clean .safety-strip strong{display:block;font-size:.93rem}
.home-clean .safety-strip span{display:block;margin-top:2px;color:#d5e4f6;font-size:.75rem;line-height:1.4}
.home-clean .safety-link{padding:9px 13px;border:1px solid rgba(255,255,255,.2);border-radius:11px;color:#fff;font-size:.72rem;font-weight:850}

/* benefits */
.home-clean .benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:34px}
.home-clean .benefit-card{position:relative;min-height:320px;overflow:hidden;padding:24px;border-radius:25px;background:linear-gradient(155deg,#eef5ff 0%,#f8fbff 100%);border:1px solid rgba(13,110,253,.08)}
.home-clean .benefit-card:nth-child(2){background:linear-gradient(155deg,#eaf6ff 0%,#f7fcff 100%)}.home-clean .benefit-card:nth-child(3){background:linear-gradient(155deg,#edf8fb 0%,#f9fcfd 100%)}
.home-clean .benefit-card h3{position:relative;z-index:2;margin:0;font-size:1.18rem;letter-spacing:-.025em}
.home-clean .benefit-card p{position:relative;z-index:2;max-width:240px;margin:7px 0 0;color:#5f6b7a;font-size:.78rem;line-height:1.5}
.home-clean .benefit-card img{position:absolute;left:0;right:0;bottom:0;width:100%;height:190px;object-fit:cover;object-position:center 48%;mask-image:linear-gradient(to bottom,transparent 0,#000 24%);-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 24%)}

/* steps */
.home-clean .step-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:42px}
.home-clean .journey-step{text-align:center}
.home-clean .step-demo{height:205px;display:flex;align-items:flex-end;justify-content:center;overflow:hidden;border-radius:20px;background:linear-gradient(180deg,#f1f6fd 0%,#f8fbff 100%)}
.home-clean .mini-phone{width:150px;min-height:178px;padding:14px 12px;border:2px solid #183454;border-bottom:0;border-radius:20px 20px 0 0;background:#fff;box-shadow:0 12px 30px rgba(13,110,253,.09)}
.home-clean .mini-brand{margin-bottom:18px;font-size:.72rem;font-weight:950}.home-clean .mini-brand em{font-style:normal;color:var(--blue)}
.home-clean .mini-line{height:8px;margin:8px 0;border-radius:99px;background:#e8ebef}.home-clean .mini-line.short{width:60%}.home-clean .mini-line.blue{background:#d9e9ff}.home-clean .mini-check{width:54px;height:54px;display:grid;place-items:center;margin:32px auto 0;border-radius:18px;background:#e9f8f1;color:#16865c;font-size:1.8rem;font-weight:900}
.home-clean .journey-step h3{margin:17px 0 5px;font-size:1.08rem;letter-spacing:-.02em}.home-clean .journey-step p{max-width:280px;margin:0 auto;color:#7a8492;font-size:.76rem;line-height:1.5}

/* FAQ */
.home-clean .faq-shell{display:grid;grid-template-columns:.68fr 1.32fr;gap:46px;padding:38px;border-radius:28px;background:linear-gradient(125deg,#071d36 0%,#0a3974 62%,#0d6efd 100%);color:#fff;box-shadow:0 24px 60px rgba(7,29,54,.18)}
.home-clean .faq-shell .home-eyebrow{color:#a8c9ef}.home-clean .faq-shell .home-title{color:#fff;font-size:clamp(1.8rem,3vw,2.8rem)}
.home-clean .faq-list{margin:0;border:0}.home-clean .faq-list details{margin-bottom:8px;border:1px solid rgba(255,255,255,.08);border-radius:12px;background:rgba(255,255,255,.09);backdrop-filter:blur(6px)}.home-clean .faq-list summary{padding:15px 17px;color:#fff;font-size:.82rem}.home-clean .faq-list summary:after{color:#fff}.home-clean .faq-list details p{padding:0 17px 16px;margin:0;color:#d6e4f5;font-size:.76rem}

/* final callout */
.home-clean .final-card{display:grid;grid-template-columns:1.15fr .85fr;gap:28px;align-items:center;padding:34px;border-radius:28px;background:linear-gradient(135deg,#f4f8ff 0%,#eef7ff 56%,#f8fdff 100%);border:1px solid rgba(13,110,253,.08)}
.home-clean .final-card .home-title{font-size:clamp(1.75rem,3vw,2.65rem)}
.home-clean .final-image{height:250px;overflow:hidden;border-radius:21px}.home-clean .final-image img{width:100%;height:100%;object-fit:cover}
.home-clean .clean-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}

@media(max-width:900px){
  .home-clean .clean-hero{padding-top:18px}.home-clean .clean-hero-shell{grid-template-columns:1fr;gap:0}.home-clean .clean-hero-visual{min-height:400px;border-radius:24px}.home-clean .clean-hero .loan-card{margin:-42px 16px 0}.home-clean .clean-hero-bottom{height:64px;margin-top:-22px}
  .home-clean .benefit-grid,.home-clean .step-grid{grid-template-columns:1fr 1fr}.home-clean .faq-shell,.home-clean .final-card{grid-template-columns:1fr}
}
@media(max-width:640px){
  .home-clean .container{width:min(calc(100% - 24px),1120px)}.home-clean .section{padding:66px 0}
  .home-clean .clean-hero-visual{min-height:350px}.home-clean .clean-hero-overlay{inset:auto 14px 14px 14px;padding:17px}.home-clean .clean-hero-overlay h1{font-size:1.9rem}
  .home-clean .clean-hero .loan-card{margin:-26px 6px 0;border-radius:22px;padding:18px}.home-clean .safety-strip{grid-template-columns:auto 1fr}.home-clean .safety-link{grid-column:1/-1;text-align:center}
  .home-clean .benefit-grid,.home-clean .step-grid{grid-template-columns:1fr}.home-clean .benefit-card{min-height:300px}.home-clean .faq-shell{padding:24px 18px}.home-clean .final-card{padding:24px 18px}.home-clean .final-image{height:210px}
}

/* Homepage above-the-fold layout and serious compact calculator.
 * Loaded after homepage.css and calculator.css so this file only overrides the hero experience.
 */

.top-strip { display: none; }

@media (min-width: 901px) {
  .site-header .nav-wrap { min-height: 68px; }

  .hero { padding: 34px 0 40px; }

  .hero-grid {
    grid-template-columns: .95fr 1.05fr;
    gap: 46px;
    align-items: center;
  }

  .hero-copy .eyebrow {
    margin-bottom: 11px;
    font-weight: 700;
    letter-spacing: .07em;
  }

  .hero-copy .display {
    max-width: 630px;
    font-size: clamp(2.65rem, 4vw, 4.15rem);
    font-weight: 800;
    line-height: 1.08;
    letter-spacing: -.035em;
  }

  .hero-copy .lead {
    max-width: 610px;
    margin-top: 15px;
    font-size: 1rem;
    line-height: 1.58;
    letter-spacing: 0;
  }

  .hero-badges { gap: 8px; margin-top: 18px; }

  .hero-badges .pill {
    padding: 7px 10px;
    font-size: .76rem;
    font-weight: 650;
    letter-spacing: .005em;
  }

  .hero-life-card {
    grid-template-columns: 118px 1fr;
    max-width: 525px;
    min-height: 92px;
    margin-top: 19px;
    border-radius: 17px;
  }

  .hero-life-card img { min-height: 92px; height: 92px; }

  .hero-life-card figcaption {
    gap: 4px;
    padding: 13px 15px;
  }

  .hero-life-card figcaption strong {
    font-size: .85rem;
    font-weight: 750;
    letter-spacing: 0;
  }

  .hero-life-card figcaption span {
    font-size: .71rem;
    line-height: 1.46;
    letter-spacing: 0;
  }
}

/* Calculator shell */
.compact-loan-calculator {
  overflow: hidden;
  border: 1px solid rgba(5,57,99,.10);
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 24px 64px rgba(5,57,99,.16);
}

.compact-calc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 60px;
  padding: 0 22px;
  border-bottom: 1px solid #e8eef3;
  background: #fff;
}

.compact-calc-head span {
  color: var(--brand-navy);
  font-size: .96rem;
  font-weight: 800;
  letter-spacing: -.01em;
}

.compact-calc-head strong {
  padding: 6px 9px;
  border-radius: 999px;
  color: #567087;
  background: #f3f7fa;
  font-size: .64rem;
  font-weight: 700;
  letter-spacing: 0;
  white-space: nowrap;
}

/* Controls */
.compact-control {
  padding: 18px 22px 0;
}

.compact-control + .compact-control {
  padding-top: 17px;
}

.compact-control-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 11px;
}

.compact-control-row > span,
.compact-control-row > label:first-child {
  color: #526b80;
  font-size: .72rem;
  font-weight: 750;
  letter-spacing: 0;
}

/* Amount should be the visual focus, not a form box. */
.compact-amount-editor {
  display: inline-flex;
  align-items: baseline;
  justify-content: flex-end;
  min-width: 154px;
  height: auto;
  padding: 0 2px 0 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.compact-amount-editor:focus-within {
  border: 0;
  background: transparent;
  box-shadow: none;
}

.compact-amount-editor span {
  margin-right: 6px;
  color: var(--brand-navy);
  font-size: 1rem;
  font-weight: 800;
}

.compact-amount-editor input {
  width: 116px;
  padding: 0 7px 0 0;
  border: 0;
  border-bottom: 1px solid transparent;
  outline: 0;
  color: var(--brand-navy);
  background: transparent;
  font: inherit;
  font-size: 1.85rem;
  font-weight: 850;
  line-height: 1.08;
  letter-spacing: -.035em;
  text-align: right;
  appearance: textfield;
  -moz-appearance: textfield;
}

.compact-amount-editor:focus-within input {
  border-bottom-color: rgba(var(--brand-primary-rgb), .32);
}

.compact-amount-editor input::-webkit-inner-spin-button,
.compact-amount-editor input::-webkit-outer-spin-button { -webkit-appearance: none; }

.compact-date-value {
  padding: 6px 10px;
  border-radius: 9px;
  color: var(--brand-navy);
  background: #f3f7fa;
  font-size: .76rem;
  font-weight: 800;
  letter-spacing: 0;
  white-space: nowrap;
}

/* Keep the wheels quiet and on-brand. */
.compact-loan-calculator .wheel-range {
  height: 6px;
  margin: 4px 0 0;
  background: linear-gradient(90deg, var(--brand-primary) 0 var(--range-progress), #dfe7ee var(--range-progress) 100%);
}

.compact-loan-calculator .wheel-range::-webkit-slider-thumb {
  width: 20px;
  height: 20px;
  border: 4px solid #fff;
  background: var(--brand-primary);
  box-shadow: 0 0 0 1px rgba(var(--brand-primary-rgb),.25), 0 3px 10px rgba(5,57,99,.16);
}

.compact-loan-calculator .wheel-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border: 4px solid #fff;
  background: var(--brand-primary);
  box-shadow: 0 0 0 1px rgba(var(--brand-primary-rgb),.25), 0 3px 10px rgba(5,57,99,.16);
}

.compact-range-ends {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  color: #7b8d9c;
  font-size: .59rem;
  font-weight: 600;
  letter-spacing: 0;
}

/* Repayment is the second-strongest element. Fees are supporting detail. */
.compact-result {
  display: grid;
  grid-template-columns: 1.35fr .65fr;
  align-items: stretch;
  margin: 17px 22px 0;
  overflow: hidden;
  border: 1px solid #e3ebf1;
  border-radius: 13px;
  background: #f7fafc;
}

.compact-result > div,
.compact-fees-button {
  min-width: 0;
  padding: 12px 14px;
}

.compact-result > div {
  border-right: 1px solid #e3ebf1;
}

.compact-result span,
.compact-result strong { display: block; }

.compact-result span {
  color: #70869a;
  font-size: .61rem;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: 0;
}

.compact-result > div strong {
  margin-top: 3px;
  color: var(--brand-navy);
  font-size: 1.32rem;
  font-weight: 850;
  line-height: 1.05;
  letter-spacing: -.025em;
}

.compact-fees-button {
  display: flex;
  flex-direction: column;
  justify-content: center;
  border: 0;
  text-align: left;
  background: transparent;
  font: inherit;
  cursor: pointer;
}

.compact-fees-button span {
  color: var(--brand-primary-strong);
  font-size: .60rem;
}

.compact-fees-button strong {
  margin-top: 3px;
  color: #415d74;
  font-size: .84rem;
  font-weight: 800;
  line-height: 1.15;
}

.compact-fees-button:hover,
.compact-fees-button:focus-visible {
  background: #eef5fa;
  outline: 0;
}

/* One confident action. */
.compact-loan-calculator .calculator-cta {
  width: calc(100% - 44px);
  min-height: 48px;
  margin: 13px 22px 19px;
  border: 0;
  border-radius: 11px;
  color: #fff;
  background: var(--brand-primary);
  box-shadow: 0 10px 22px rgba(var(--brand-primary-rgb), .22);
  font-size: .91rem;
  font-weight: 800;
  letter-spacing: -.005em;
}

.compact-loan-calculator .calculator-cta:hover {
  background: var(--brand-primary-strong);
  box-shadow: 0 12px 26px rgba(var(--brand-primary-rgb), .28);
}

/* Mobile is calculator-first. Do not make a borrower read the desktop sales hero first. */
@media (max-width: 900px) {
  .hero {
    padding: 10px 0 22px;
    min-height: 0;
  }

  .hero .container.hero-grid {
    width: min(calc(100% - 16px), 620px);
  }

  .hero-grid {
    display: block;
  }

  .hero-copy {
    display: none;
  }

  .compact-loan-calculator {
    width: 100%;
    margin: 0 auto;
    border-radius: 17px;
    box-shadow: 0 14px 34px rgba(5,57,99,.14);
  }

  .compact-calc-head,
  .compact-control {
    padding-left: 18px;
    padding-right: 18px;
  }

  .compact-result {
    margin-left: 18px;
    margin-right: 18px;
  }

  .compact-loan-calculator .calculator-cta {
    width: calc(100% - 36px);
    margin-left: 18px;
    margin-right: 18px;
  }

  .section-tight {
    padding-top: 0;
  }
}

@media (max-width: 520px) {
  .hero { padding-top: 8px; padding-bottom: 16px; }

  .compact-calc-head {
    min-height: 54px;
    align-items: center;
    padding-left: 15px;
    padding-right: 15px;
  }

  .compact-calc-head strong {
    max-width: 132px;
    padding: 5px 7px;
    white-space: normal;
    text-align: right;
    line-height: 1.25;
  }

  .compact-control {
    padding-left: 15px;
    padding-right: 15px;
  }

  .compact-control-row { gap: 10px; }

  .compact-amount-editor {
    min-width: 134px;
    padding-right: 1px;
  }

  .compact-amount-editor input {
    width: 102px;
    padding-right: 5px;
    font-size: 1.65rem;
    line-height: 1.08;
  }

  .compact-result {
    grid-template-columns: 1.2fr .8fr;
    margin-left: 15px;
    margin-right: 15px;
  }

  .compact-result > div,
  .compact-fees-button {
    padding: 11px 12px;
  }

  .compact-result > div strong { font-size: 1.18rem; }

  .compact-loan-calculator .calculator-cta {
    width: calc(100% - 30px);
    min-height: 50px;
    margin: 12px 15px 15px;
  }
}
